package com.wizzadrds.theworldremembers.knowledge; import org.junit.jupiter.api.Test; import java.util.UUID; import static org.junit.jupiter.api.Assertions.*; class KnowledgeManagerTest{@Test void reportsDegradeAndPreserveSource(){UUID a=UUID.randomUUID(),b=UUID.randomUUID(),s=UUID.randomUUID();var k=new KnowledgeManager();k.remember(new KnowledgeFact(a,"npc_died",s,null,KnowledgeProvenance.DIRECT,100,1,0));k.report(a,b,"npc_died",s,110);var f=k.facts(b).get(0);assertEquals(KnowledgeProvenance.REPORTED,f.provenance());assertEquals(a,f.source());assertTrue(f.confidence()<1);}}
